INSERT INTO feature VALUES('checkpoint-restriction','incremental','A checkpoint set restricts to a closure inside it by keys','incremental-checking','implemented','notable',NULL,'A bundle cuts a checked set at the sources that a front end states, and holds each source''s run of checkpoints under a key that digests the content keys of its items and the keys of its imports. The set of an import closure restricts to the set of each closure inside it by the keys of that closure''s sources. The restriction judges no item and encodes no item of the larger set, and it gives the set that a fresh check of the smaller closure gives. A source beside an item that holds an unresolved id has no key, so its closure is walked instead.','core-incremental surface-dispatcher','crates/core-incremental/src/bundle/tests.rs crates/surface-dispatcher/tests/locality.rs','crate-tests',NULL);
